405		if domainPausedFailedPostCopy(domain) {
406			if vmi.Status.Phase == v1.Running {
407				// In this function, we can usually clean up our (target) pod, since the migration is over.
408				// However, there is one specific case where we can't: on post-copy migration failure that hasn't been acted on at the VMI level yet.
409				// This is because, in that specific scenario, the source of truth is in the libvirt domain running in our pod.
410				// Once we terminate our pod, the information is gone.
411				c.logger.Object(vmi).Info("we're the target of a failed post-copy but the VMI is still running, waiting a sec")
412				c.queue.AddAfter(controller.VirtualMachineInstanceKey(vmi), time.Second*1)
413				return nil
414			}
415			if vmi.Status.Phase == v1.Succeeded {
416				// Ensuring failed post-copy migrations don't lead to a successful VMI, shouldn't be needed
417				c.logger.Object(vmi).Warning("VMI status wrongly set to succeeded, this shouldn't happen, fixing VMI phase")
418				vmi.Status.Phase = v1.Failed
419			}
420		}
421	
422		defer c.migrationProxy.StopTargetListener(string(vmi.UID))
423		defer c.launcherClients.CloseLauncherClient(vmi)
424		client, err := c.launcherClients.GetLauncherClient(vmi)
425		if err != nil {
426			return err
427		}
428	
429		if vmi.Status.MigrationState.Failed {
430			err = client.SignalTargetPodCleanup(vmi)
431			if err != nil {
432				c.logger.Object(vmi).Warningf("Failed to signal target pod cleanup: %v, ignoring.", err)
433			}
434			err = c.unmountVolumes(vmi)
435			if err != nil {
436				return err
437			}
438			c.logger.Object(vmi).Infof("Signaled target pod for failed migration to clean up")
439	
440			// tear down network cache
441			if err = c.netConf.Teardown(vmi); err != nil {
442				return fmt.Errorf("failed to delete VMI Network cache files: %s", err.Error())
443			}
444			c.netStat.Teardown(vmi)
445			// The migration failed. As the target virt-handler, the domain doesn't belong to our store anymore
446			if err = c.domainStore.Delete(vmi); err != nil {
447				return err
448			}
449		} else {
450			options := &cmdv1.VirtualMachineOptions{}
451			options.InterfaceMigration = domainspec.BindingMigrationByInterfaceName(vmi.Spec.Domain.Devices.Interfaces, c.clusterConfig.GetNetworkBindings())
