// migrationTargetFailed reports whether the migration this VMI is a target of has already failed.
func migrationTargetFailed(vmi *virtv1.VirtualMachineInstance) bool {
	return vmi.Status.MigrationState != nil &&
		vmi.Status.MigrationState.Failed &&
		vmi.Status.MigrationState.Completed
}

// markMigrationFailed marks the VMI's migration state as a failed, completed migration.
// An existing StartTimestamp is preserved unchanged; the EndTimestamp is always set to the
// current time and both Completed and Failed are set to true.
func markMigrationFailed(vmi *virtv1.VirtualMachineInstance) {
	if vmi.Status.MigrationState == nil {
		vmi.Status.MigrationState = &virtv1.VirtualMachineInstanceMigrationState{}
	}
	vmi.Status.MigrationState.EndTimestamp = pointer.P(metav1.Now())
	vmi.Status.MigrationState.Completed = true
	vmi.Status.MigrationState.Failed = true
